def getHappyString(n: int, k: int) -> str:
    def generate_happy(index, current, last_char):
        if index == n:
            results.append("".join(current))
            return
        for char in ['a', 'b', 'c']:
            if char != last_char:
                current.append(char)
                generate_happy(index + 1, current, char)
                current.pop()

    results = []
    generate_happy(0, [], '')

    if k > len(results):
        return ""

    return results[k - 1]
